  (function cloudflareTableConfig() {
    function tablePrefKey(tableId) {
      const user = document.getElementById("messenger-link")?.getAttribute("data-me") || "anonymous";
      const target = document.getElementById("sidebar-server-switcher")?.getAttribute("data-current-target-id")
        || sessionStorage.getItem("panel-active-target-scope") || "local";
      return `lxp:prefs:${encodeURIComponent(user)}:${encodeURIComponent(target)}:data-table:${tableId}`;
    }
    const PAGE_SIZES = [10, 25, 50, 100];
    function read(tableId) {
      try {
        const raw = localStorage.getItem(tablePrefKey(tableId));
        if (raw) { const c = JSON.parse(raw); return { pageSize: Number(c.pageSize) || 25, hiddenActions: Array.isArray(c.hiddenActions) ? c.hiddenActions.map(String) : [] }; }
      } catch {}
      return { pageSize: 25, hiddenActions: [] };
    }
    function write(tableId, cfg) {
      try { localStorage.setItem(tablePrefKey(tableId), JSON.stringify(cfg)); } catch {}
      window.dispatchEvent(new CustomEvent("lxp:data-table:apply-prefs", { detail: { tableId, pageSize: cfg.pageSize, hiddenActions: cfg.hiddenActions } }));
    }
    function reflect(tableId) {
      const cfg = read(tableId);
      document.querySelectorAll(`[data-cf-pagesize][data-cf-table="${tableId}"]`).forEach((btn) => {
        const on = Number(btn.getAttribute("data-cf-pagesize")) === cfg.pageSize;
        btn.classList.toggle("bg-primary/10", on); btn.classList.toggle("text-primary", on); btn.classList.toggle("border-primary/40", on); btn.classList.toggle("text-muted-foreground", !on);
      });
      document.querySelectorAll(`[data-cf-action-toggle][data-cf-table="${tableId}"]`).forEach((cb) => {
        cb.checked = !cfg.hiddenActions.includes(cb.getAttribute("data-cf-action-toggle"));
      });
    }
    const tableIds = Array.from(new Set(Array.from(document.querySelectorAll("[data-cf-view]")).map((el) => el.getAttribute("data-cf-view"))));
    // Left-nav switching
    document.querySelectorAll("[data-cf-settings-nav]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const view = btn.getAttribute("data-cf-settings-nav");
        document.querySelectorAll("[data-cf-view]").forEach((sec) => sec.classList.toggle("hidden", sec.getAttribute("data-cf-view") !== view));
        document.querySelectorAll("[data-cf-settings-nav]").forEach((b) => {
          const on = b === btn;
          b.classList.toggle("bg-primary/10", on); b.classList.toggle("text-primary", on); b.classList.toggle("text-muted-foreground", !on);
        });
        if (view) reflect(view);
      });
    });
    // Pagination
    document.querySelectorAll("[data-cf-pagesize]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const tableId = btn.getAttribute("data-cf-table"); const size = Number(btn.getAttribute("data-cf-pagesize"));
        if (!tableId || !PAGE_SIZES.includes(size)) return;
        const cfg = read(tableId); cfg.pageSize = size; write(tableId, cfg); reflect(tableId);
      });
    });
    // Action toggles
    document.querySelectorAll("[data-cf-action-toggle]").forEach((cb) => {
      cb.addEventListener("change", () => {
        const tableId = cb.getAttribute("data-cf-table"); const id = cb.getAttribute("data-cf-action-toggle");
        if (!tableId || !id) return;
        const cfg = read(tableId); const set = new Set(cfg.hiddenActions);
        if (cb.checked) set.delete(id); else set.add(id);
        cfg.hiddenActions = Array.from(set); write(tableId, cfg);
      });
    });
    tableIds.forEach(reflect);
  })();

