  function initDbSettingsDrawer() {
    const TABLES = ["db-structure-table", "db-console-table"];
    const ACTIVE = ["bg-primary/10", "text-primary"];
    const INACTIVE = ["text-muted-foreground", "hover:bg-accent", "hover:text-foreground"];
    function tablePrefKey(tableId) {
      const user = document.getElementById("messenger-link")?.getAttribute("data-me") || "anonymous";
      const target = document.getElementById("sidebar-server-switcher")?.getAttribute("data-current-target-id")
        || sessionStorage.getItem("panel-active-target-scope") || "local";
      return `lxp:prefs:${encodeURIComponent(user)}:${encodeURIComponent(target)}:data-table:${tableId}`;
    }
    function readPref(id) { try { const raw = localStorage.getItem(tablePrefKey(id)); return raw ? JSON.parse(raw) : {}; } catch { return {}; } }
    function writePagesize(size) {
      TABLES.forEach((id) => {
        const cfg = readPref(id); cfg.pageSize = size; if (!Array.isArray(cfg.hiddenActions)) cfg.hiddenActions = [];
        try { localStorage.setItem(tablePrefKey(id), JSON.stringify(cfg)); } catch (e) {}
        window.dispatchEvent(new CustomEvent("lxp:data-table:apply-prefs", { detail: { tableId: id, pageSize: size, hiddenActions: cfg.hiddenActions } }));
      });
    }
    function reflectPagesize() {
      const cur = readPref(TABLES[0]).pageSize || 20;
      document.querySelectorAll("[data-db-pagesize]").forEach((btn) => {
        const on = Number(btn.getAttribute("data-db-pagesize")) === cur;
        btn.classList.toggle("bg-primary", on); btn.classList.toggle("text-primary-foreground", on);
      });
    }
    document.querySelectorAll("[data-db-pagesize]").forEach((btn) => {
      btn.addEventListener("click", () => { writePagesize(Number(btn.getAttribute("data-db-pagesize"))); reflectPagesize(); });
    });
    function showView(view) {
      document.querySelectorAll("[data-db-settings-view]").forEach((el) => el.classList.toggle("hidden", el.getAttribute("data-db-settings-view") !== view));
      document.querySelectorAll("[data-db-settings-nav]").forEach((btn) => {
        const on = btn.getAttribute("data-db-settings-nav") === view;
        ACTIVE.forEach((c) => btn.classList.toggle(c, on));
        INACTIVE.forEach((c) => btn.classList.toggle(c, !on));
      });
      if (view === "tabla") reflectPagesize();
    }
    document.querySelectorAll("[data-db-settings-nav]").forEach((btn) => {
      btn.addEventListener("click", () => showView(btn.getAttribute("data-db-settings-nav") || "tabla"));
    });
    const CW_KEY = "lxp:databases:console-allow-write";
    let cw = false; try { cw = localStorage.getItem(CW_KEY) === "1"; } catch (e) {}
    const cwBox = document.getElementById("db-cfg-allow-write");
    if (cwBox) {
      cwBox.checked = cw;
      cwBox.addEventListener("change", () => {
        try { localStorage.setItem(CW_KEY, cwBox.checked ? "1" : "0"); } catch (e) {}
        const live = document.getElementById("sql-allow-write"); if (live) live.checked = cwBox.checked;
      });
    }
    const live = document.getElementById("sql-allow-write"); if (live && cw) live.checked = true;
    reflectPagesize();
  }
  document.addEventListener("astro:page-load", initDbSettingsDrawer);

