    }
    function key() { return tablePrefKey(TABLE_ID); }
    const PAGE_SIZES = [10, 25, 50, 100];

    function readCfg() {
      try {
        const raw = localStorage.getItem(key());
        if (raw) {
          const c = JSON.parse(raw);
          return { pageSize: Number(c.pageSize) || 25, hiddenActions: Array.isArray(c.hiddenActions) ? c.hiddenActions.map(String) : [] };
        }
      } catch (_) {}
      return { pageSize: 25, hiddenActions: [] };
    }
    function writeCfg(cfg) {
      try { localStorage.setItem(key(), JSON.stringify(cfg)); } catch (_) {}
      window.dispatchEvent(new CustomEvent("lxp:data-table:apply-prefs", { detail: { tableId: TABLE_ID, pageSize: cfg.pageSize, hiddenActions: cfg.hiddenActions } }));
    }
    function scope() { return document.getElementById("hosting-settings-modal"); }
    function reflect() {
      const root = scope(); if (!root) return;
      const cfg = readCfg();
      root.querySelectorAll("[data-hosting-pagesize]").forEach(function (btn) {
        const on = Number(btn.getAttribute("data-hosting-pagesize")) === cfg.pageSize;
        btn.classList.toggle("bg-primary", on);
        btn.classList.toggle("text-primary-foreground", on);
        btn.classList.toggle("text-muted-foreground", !on);
      });
      root.querySelectorAll("[data-hosting-action-toggle]").forEach(function (cb) {
        cb.checked = cfg.hiddenActions.indexOf(cb.getAttribute("data-hosting-action-toggle")) === -1;
      });
    }

    document.addEventListener("click", function (e) {
      const t = e.target instanceof Element ? e.target : null;
      if (!t) return;
      const ps = t.closest("[data-hosting-pagesize]");
      if (ps && scope() && scope().contains(ps)) {
        const cfg = readCfg(); cfg.pageSize = Number(ps.getAttribute("data-hosting-pagesize")) || 25; writeCfg(cfg); reflect(); return;
      }
      const all = t.closest("[data-hosting-actions-all]");
      if (all && scope() && scope().contains(all)) {
        const cfg = readCfg();
        const ids = Array.prototype.map.call(scope().querySelectorAll("[data-hosting-action-toggle]"), function (cb) { return cb.getAttribute("data-hosting-action-toggle"); });
        cfg.hiddenActions = all.getAttribute("data-hosting-actions-all") === "hide" ? ids.slice() : [];
        writeCfg(cfg); reflect(); return;
      }
      if (t.closest("#hosting-settings-modal-trigger")) { setTimeout(reflect, 0); }
    });
    document.addEventListener("change", function (e) {
      const cb = e.target instanceof Element ? e.target.closest("[data-hosting-action-toggle]") : null;
      if (!cb || !scope() || !scope().contains(cb)) return;
      const id = cb.getAttribute("data-hosting-action-toggle");
      const cfg = readCfg();
      const i = cfg.hiddenActions.indexOf(id);
      if (cb.checked) { if (i !== -1) cfg.hiddenActions.splice(i, 1); }
      else { if (i === -1) cfg.hiddenActions.push(id); }
      writeCfg(cfg);
    });
    reflect();
    document.addEventListener("astro:page-load", reflect);
  })();

